package com.tripnest.crud.controller;
import com.tripnest.crud.service.DashboardService; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final DashboardService service; public DashboardController(DashboardService service){this.service=service;} @GetMapping("/company") public ResponseEntity<Map<String,Object>> company(@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(service.company(jwt));} @GetMapping("/admin") public ResponseEntity<Map<String,Object>> admin(@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(service.admin(jwt));}}
